import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK","description":"官方 SDK 只封装原生 JSON。每种语言一页：安装、Quick start、完整参考。","frontmatter":{"title":"SDK","description":"官方 SDK 只封装原生 JSON。每种语言一页：安装、Quick start、完整参考。"},"headers":[],"relativePath":"api/sdk/index.md","filePath":"api/sdk/index.md","lastUpdated":1790057721000}`),a={name:`api/sdk/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk" tabindex="-1">SDK <a class="header-anchor" href="#sdk" aria-label="Permalink to “SDK”">​</a></h1><p>官方 SDK 只封装<strong>原生 JSON</strong>（检查更新、下载、校验、可选差量/打包、可选替换）。<strong>不做</strong> Sparkle / electron-updater / WinGet 等商店协议。</p><p>阅读顺序：安装 → Quick start 完成一次 <code>check</code>；需要自定义 Transport / 差量 / 占用文件替换 / 嵌入式网络时阅读该语言页后半与 <a href="./concepts">概念</a>。商店协议见指南中的 Electron/Sparkle 等页。</p><p>文档示例版本号（如 <code>0.1.0</code>）会过时；安装时以 registry 当前版本为准。</p><h2 id="安装对照" tabindex="-1">安装对照 <a class="header-anchor" href="#安装对照" aria-label="Permalink to “安装对照”">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>怎么装进应用</th><th>最低环境</th><th>源码 git 分支</th></tr></thead><tbody><tr><td>Python</td><td><code>pip install kirivers-client</code></td><td>Python 3.10+</td><td><code>sdk/python</code></td></tr><tr><td>Java</td><td>Maven <code>official.kirizu:kirivers-client</code></td><td>JDK 17</td><td><code>sdk/java</code></td></tr><tr><td>Kotlin</td><td><code>official.kirizu:kirivers-client-kotlin</code>（独立包，不是 Java 包装）</td><td>JDK 17</td><td><code>sdk/kotlin</code></td></tr><tr><td>C#</td><td><code>dotnet add package Kirizu.KiriVers.Client</code></td><td>.NET 8</td><td><code>sdk/csharp</code></td></tr><tr><td>TypeScript</td><td><code>npm install @kirizu/kirivers-client</code></td><td>Node 20+ / Electron 主进程；<strong>不能用于网页</strong></td><td><code>sdk/typescript</code></td></tr><tr><td>Rust</td><td>crates.io <code>kirivers-client</code></td><td>阻塞 API，不必 tokio</td><td><code>sdk/rust</code></td></tr><tr><td>Dart</td><td><code>dart pub add kirivers_client</code></td><td>Dart 3；Flutter 应用可用、<strong>Web 不行</strong></td><td><code>sdk/dart</code></td></tr><tr><td>C</td><td><code>git clone -b sdk/c https://github.com/Kirizu-Official/KiriVers.git</code></td><td>C11；CMake hosted 或 embedded</td><td><code>sdk/c</code></td></tr><tr><td>C++</td><td><code>git clone -b sdk/cpp …</code></td><td>C++17</td><td><code>sdk/cpp</code></td></tr><tr><td>Go</td><td><code>go get github.com/Kirizu-Official/KiriVers-SDK-Go</code>（<strong>独立仓</strong>）</td><td>Go 模块</td><td>发布仓；本仓源码 <code>sdk/go-src</code>；<code>sdk/go</code> 仅跳转</td></tr><tr><td>PHP</td><td><code>composer require kirizu/kirivers-client</code>（仓 <code>KiriVers-SDK-PHP</code>）</td><td>PHP 8.2+，不要装 Guzzle</td><td><code>sdk/php-src</code>；<code>sdk/php</code> 仅跳转</td></tr><tr><td>Swift</td><td>SPM <code>https://github.com/Kirizu-Official/KiriVers-SDK-Swift.git</code></td><td>Apple 工具链；不要把主仓加进 Xcode</td><td><code>sdk/swift-src</code>；<code>sdk/swift</code> 仅跳转</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">包尚未上架或独立仓尚未公开</p><p>同一语言页给出 clone 对应分支的退路。<strong>禁止</strong> <code>go get</code> / Packagist / SPM 指向本仓 <code>main</code> 或跳转分支 <code>sdk/go</code>、<code>sdk/php</code>、<code>sdk/swift</code>。</p></div><h2 id="所有语言共通" tabindex="-1">所有语言共通 <a class="header-anchor" href="#所有语言共通" aria-label="Permalink to “所有语言共通”">​</a></h2><ol><li>调用方提供 <code>base_url</code>、<code>project_ref</code>、当前版本、os/arch、渠道，以及由应用生成并稳定保存的 <code>device_id</code>（SDK 不生成设备身份）。</li><li>HTTP 204 / <code>no_update</code> 表示已是最新，不是错误；304 为 ETag 命中。</li><li>未注入 Replacer 时不得描述为一键安装。</li><li>未注入 Patcher 时不得申报 <code>binary_delta</code>。</li></ol>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};